class DictionaryPanel{constructor(){this.wordListEl=document.getElementById("wordList"),this.searchInputEl=document.getElementById("searchInput"),this.addWordBtnEl=document.getElementById("addWordBtn"),this.newWordKanjiEl=document.getElementById("newWordKanji"),this.newWordReadingEl=document.getElementById("newWordReading"),this.wordCountEl=document.getElementById("wordCount"),this.currentQuery="",this.debouncedSearch=this.debounce(this.performSearch.bind(this),250),this.init()}async init(){this.bindEvents(),await this.loadInitialData()}bindEvents(){this.searchInputEl.addEventListener("input",t=>{this.currentQuery=t.target.value,console.log("Sidepanel: Search input changed. Query:",this.currentQuery),this.debouncedSearch(this.currentQuery)}),this.addWordBtnEl.addEventListener("click",()=>this.addWord()),this.wordListEl.addEventListener("click",t=>{t.target.classList.contains("delete-btn")&&this.deleteWord(t.target.dataset.kanji)})}toKatakana(t){return t.replace(/[\u3040-\u309F]/g,function(t){const e=t.charCodeAt(0)+96;return String.fromCharCode(e)})}async loadInitialData(){console.log("Sidepanel: Loading initial data...");try{const t=await chrome.runtime.sendMessage({type:"GET_STATISTICS"});t&&t.success&&(this.wordCountEl.textContent=t.statistics.totalWords,console.log("Sidepanel: Dictionary stats loaded:",t.statistics)),await this.performSearch("")}catch(t){console.error("Sidepanel: Error loading initial data:",t),this.wordListEl.innerHTML=`<div class="word-item">${this.toKatakana("データノヨミコミチュウニエラーガハッセイシマシタ。")}</div>`}}async performSearch(t){console.log("Sidepanel: Performing search for query:",t);try{const e=await chrome.runtime.sendMessage({type:"SEARCH_DICTIONARY",query:t});if(!e||!e.success)throw console.error("Sidepanel: Search failed. Response:",e),new Error(e?.error||"SEARCH FAILED");console.log("Sidepanel: Search response received:",e.results),this.renderWordList(e.results)}catch(t){console.error("Sidepanel: Error performing search:",t),this.wordListEl.innerHTML=`<div class="word-item">${this.toKatakana("ケンサクチュウニエラーガハッセイシマシタ。")}</div>`}}renderWordList(t){if(this.wordListEl.innerHTML="",0!==t.length)for(const e of t){const t=document.createElement("div");t.className="word-item",t.innerHTML=`\n          <div class="word-display">\n              <span class="word-kanji">${e.kanji}</span>\n              <span class="word-reading">${e.reading} (${e.romaji.toUpperCase()})</span>\n          </div>\n          <button class="delete-btn" data-kanji="${e.kanji}">${this.toKatakana("サクジョ")}</button>\n      `,this.wordListEl.appendChild(t)}else this.wordListEl.innerHTML=`<div class="word-item">${this.toKatakana("ガイタウスルタンゴハアリマセン。")}</div>`}async addWord(){const t=this.newWordKanjiEl.value.trim(),e=this.newWordReadingEl.value.trim();if(t&&e)try{const a=await chrome.runtime.sendMessage({type:"ADD_TO_DICTIONARY",kanji:t,reading:e});a&&a.success?(this.newWordKanjiEl.value="",this.newWordReadingEl.value="",await this.loadInitialData()):alert(this.toKatakana("タンゴノツイカニシッパイシマシタ:")+a?.error)}catch(t){console.error("Error adding word:",t),alert(this.toKatakana("タンゴノツイカチュウニエラーガハッセイシマシタ。"))}else alert(this.toKatakana("タンゴトヨミヲリョウホウニュウリョクシテクダサイ。"))}async deleteWord(t){if(confirm(`${this.toKatakana("「")}${t}${this.toKatakana("」ヲジショカラサクジョシマスカ？")}`))try{const e=await chrome.runtime.sendMessage({type:"REMOVE_FROM_DICTIONARY",kanji:t});e&&e.success?await this.loadInitialData():alert(this.toKatakana("タンゴノサクジョニシッパイシマシタ。"))}catch(t){console.error("Error deleting word:",t),alert(this.toKatakana("サクジョチュウニエラーガハッセイシマシタ:")+t.message)}}debounce(t,e){let a;return function(...n){clearTimeout(a),a=setTimeout(()=>{clearTimeout(a),t(...n)},e)}}}document.addEventListener("DOMContentLoaded",()=>new DictionaryPanel);